<script setup lang="ts">
// Renders an icon class name. `i-vscode-icons-*` file-type icons are served as static SVGs from
// public/icons/vscode (generated by scripts/generate-vscode-icons.mjs) so they stay out of the
// global UnoCSS bundle; every other icon falls through to its UnoCSS class.
const props = defineProps<{
	icon: string
}>()

const VSCODE_PREFIX = 'i-vscode-icons-'

const src = computed(() =>
	props.icon.startsWith(VSCODE_PREFIX) ? `/icons/vscode/${props.icon.slice(VSCODE_PREFIX.length)}.svg` : '')
</script>

<template>
	<img
		v-if="src"
		:src="src"
		alt=""
		aria-hidden="true"
		loading="lazy"
		decoding="async"
		width="16"
		height="16"
		class="inline-block h-[1.2em] w-[1.2em] align-middle"
	>
	<span
		v-else
		:class="icon"
		aria-hidden="true"
	/>
</template>
